private val usernameRegex = "^[A-Za-z0-9._-]+$".toRegex()

private val oldestYear = 1900

private val currentDate = LocalDate.now()

private suspend fun validateAllInputs(): Boolean {
  val state = _uiState.value
  val firstNameErr = validateName(state.firstName, "First name", InputLimits.FIRST_NAME)
  if (firstNameErr != null) {
    setErrorMsg(firstNameErr)
    return false
  }

  val lastNameErr = validateName(state.lastName, "Last name", InputLimits.LAST_NAME)
  if (lastNameErr != null) {
    setErrorMsg(lastNameErr)
    return false
  }

  if (!validateDescription(state.description)) {
    return false
  }

  if (!validateDate(state.day, state.month, state.year)) {
    return false
  }

  if (!validateCountry(state.country)) {
    return false
  }

  if (!validateUsername(state.username)) {
    return false
  }

  return true
}

/**
 * Generic validation function for text fields.
 * 
 * @return `true` if valid, `false` otherwise, setting an error message on failure.
 */
private fun validate(value: String, fieldName: String, maxLength: Int, regex: Regex): Boolean {
  return when {
    value.isBlank() -> {
      setErrorMsg("$fieldName cannot be empty")
      false
    }
    value.length > maxLength -> {
      setErrorMsg("$fieldName is too long")
      false
    }
    !regex.matches(value) -> {
      setErrorMsg("Invalid $fieldName format")
      false
    }
    else -> true
  }
}

/**
 * Validates the description field.
 * 
 * @return `true` if valid, `false` otherwise, setting an error message on failure.
 */
private fun validateDescription(description: String?): Boolean {
  if (description != null) {
    val error = com.android.universe.ui.common.validateDescription(description, InputLimits.DESCRIPTION)
    if (error != null) {
      setErrorMsg(error)
      return false
    }
  }
  return true
}

/**
 * Validates the date fields and the user's age.
 * 
 * @return `true` if valid, `false` otherwise, setting an error message on failure.
 */
private fun validateDate(dayStr: String, monthStr: String, yearStr: String): Boolean {
  val (dayErr, monthErr, yearErr) = com.android.universe.ui.common.validateDateTriple(dayStr, monthStr, yearStr)
  val error = dayErr ?: monthErr ?: yearErr
  if (error != null) {
    setErrorMsg(error)
    return false
  }
  return true
}

/**
 * Validates the country field.
 * 
 * @return `true` if valid, `false` otherwise, setting an error message on failure.
 */
private fun validateCountry(country: String): Boolean {
  val error = com.android.universe.ui.common.validateNonEmpty("Country", country)
  if (error != null) {
    setErrorMsg(error)
    return false
  }
  if (countryToIsoCode[country] == null) {
    setErrorMsg("Invalid country")
    return false
  }
  return true
}

/**
 * Validates the username for format, length, and uniqueness.
 * 
 * @return `true` if valid, `false` otherwise, setting an error message on failure.
 */
private suspend fun validateUsername(username: String): Boolean {
  if (!validate(username, "Username", InputLimits.USERNAME, usernameRegex)) {
    return false
  }

  if (!repository.isUsernameUnique(username)) {
    setErrorMsg("Username already exists")
    return false
  }

  return true
}

fun setDescription(description: String) {
  val cleaned = trimAndCleanInput(description, InputLimits.DESCRIPTION + 1)
  val error = com.android.universe.ui.common.validateDescription(cleaned, InputLimits.DESCRIPTION)
  _uiState.value = _uiState.value.copy(description = cleaned, descriptionError = error)
}

